import{_ as o,o as t,c as d,a2 as a}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"静默失败 — 什么都不打印的时候","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/silent-failures.md","filePath":"zh/troubleshooting/silent-failures.md"}'),c={name:"zh/troubleshooting/silent-failures.md"};function l(s,e,r,n,i,p){return t(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="静默失败-—-什么都不打印的时候" tabindex="-1">静默失败 — 什么都不打印的时候 <a class="header-anchor" href="#静默失败-—-什么都不打印的时候" aria-label="Permalink to &quot;静默失败 — 什么都不打印的时候&quot;">​</a></h1><p>Open Cube OS 的多数失败很吵：错误串、<code>FAIL</code> 判定、 panic 横幅。本页讲另一类：<strong>不打印任何东西</strong>就出错的 情形、设计为何让它们安静、以及让它们现形的准确 命令。读一遍；它会为你省下一个下午。</p><p>一行规则：<strong>先 <code>health</code>，再 <code>dmesg 100</code>，然后 <code>crashlog</code>。</strong> 这三样几乎能看穿每一次静默失败。</p><hr><h2 id="_1-输出捕获-—-当你的控制台什么都不显示-因为文本" tabindex="-1">1. 输出捕获 — 当你的控制台什么都不显示，因为文本 <a class="header-anchor" href="#_1-输出捕获-—-当你的控制台什么都不显示-因为文本" aria-label="Permalink to &quot;1. 输出捕获 — 当你的控制台什么都不显示，因为文本&quot;">​</a></h2><p>进了缓冲</p><h3 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h3><p>多数服务 op 是 v2.2.0 的 shell 命令体，经 <code>screen_console_puts</code> 打印。为了通过 L1SVC 系统调用提供 它们，分发器将其包进 <code>core_kcap_run_fn(fn, arg, out, cap)</code>：</p><ul><li>捕获活跃期间，捕获钩子<strong>就是控制台钩子</strong> （控制台驱动只持有一个钩子槽）。</li><li>字符进入调用方的缓冲；framebuffer 绘制 和串口分流在此期间均被<strong>抑制</strong>。</li><li>捕获最多叠 4 层；最后一个捕获结束时重新安装 引导串口分流。</li><li>溢出&quot;以标记上报，绝不静默截断&quot;。</li></ul><p>你会实际遇到的后果：</p><ul><li>从向导或脚本运行的命令<strong>不实时打印</strong> — 其输出进入捕获缓冲，由调用方渲染。 这是正确的，不是失败。</li><li>如果被捕获的命令体循环或等待控制台输入，机器看起来 像死了：提示符再也不回来。</li></ul><h3 id="三种路由风格-为何有些-op-实时打印而另一些不" tabindex="-1">三种路由风格（为何有些 op 实时打印而另一些不） <a class="header-anchor" href="#三种路由风格-为何有些-op-实时打印而另一些不" aria-label="Permalink to &quot;三种路由风格（为何有些 op 实时打印而另一些不）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风格</th><th>op</th><th>原因</th></tr></thead><tbody><tr><td><strong>captured</strong>（<code>core_kcap_run_fn</code>）</td><td>多数一次性文本 op（状态、列表、测试）</td><td>输出属于调用方</td></tr><tr><td><strong>direct</strong>（<code>out[0]=0; return fn(arg);</code>）</td><td><code>sshd</code>、全部 9 个 TUI op、<code>ime -i</code>、<code>power sleep</code></td><td>被捕获的命令体不得睡眠 —— 被捕获运行时它们吞掉了实时控制台输出（在 OCIRE 监督引导期间现场发现）</td></tr><tr><td><strong>buffer-render</strong>（服务自己写 <code>out</code>）</td><td>l1、klog、health、diag、fs、time、watchdog 分发器</td><td>不涉及遗留打印体</td></tr></tbody></table><p>所以当 <code>power sleep 2</code> 实时打印倒计时而 <code>health</code> 直到 返回都不回显 — 那是路由表，不是 bug。而如果你从 <code>sshd</code> 或某个 TUI 页面看到<strong>完全没有输出</strong>，检查串口 控制台：direct 路由的输出偏好实时 控制台，在慢终端上可能被漏看。</p><h2 id="_2-返回值约定-—-无-errno-可读" tabindex="-1">2. 返回值约定 — 无 errno 可读 <a class="header-anchor" href="#_2-返回值约定-—-无-errno-可读" aria-label="Permalink to &quot;2. 返回值约定 — 无 errno 可读&quot;">​</a></h2><p><strong>没有全局 <code>errno</code> 变量也没有 <code>errno.h</code></strong>（freestanding 内核，无 libc）：</p><ul><li>0 = 成功，负数 = 失败（<code>-1</code> 为通用）。</li><li>精度来自 8 个稠密负数枚举家族（61 个代码 — <a href="./error-codes.html">error-codes.md</a>）。</li><li>环形缓冲 API 返回 ≥ 0 的槽索引；<code>-1</code> = 越过窗口。</li><li>watchdog 槽位 API 返回 -1（表满）/ -2（参数错误）。</li></ul><p>陷阱：一个以 <code>-1</code> 失败且不打印的命令（参数合法但 操作被拒，例如写 OCIRE 保护的恢复盘）在<strong>任何地方都 不留下消息</strong>，除非服务自己选择写入 klog。当命令&quot;什么 都没做&quot;：</p><ol><li>重新运行并在第二步观察 <code>dmesg 30</code> — 许多拒绝是 klog WARN/ERROR 行，不是控制台行。</li><li>检查该家族的 <code>_test</code> 桩 — 它以可见的判定 演练同一 op。</li><li>记住刻意的拒绝：写恢复盘 （<code>blk: write ... REFUSED</code> 仅在 klog）、杀 ocire_guard （看起来像&quot;no such process&quot;）。</li></ol><h2 id="_3-如实跳过-模式-—-一个-pass-形状的非答案" tabindex="-1">3. &quot;如实跳过&quot;模式 — 一个 PASS 形状的非答案 <a class="header-anchor" href="#_3-如实跳过-模式-—-一个-pass-形状的非答案" aria-label="Permalink to &quot;3. &quot;如实跳过&quot;模式 — 一个 PASS 形状的非答案&quot;">​</a></h2><p>硬件缺失条件刻意报告 <code>(honest skip)</code> / <code>(honest FAIL)</code> 而不是让套件失败。示例：</p><ul><li><code>hpet: legacy route not available (honest skip)</code></li><li><code>oneshot: arm failed (honest FAIL)</code></li><li><code>[audio_rw_test] no sound cards registered =&gt; SKIPPED</code></li><li><code>msitest</code> 的 <code>e1000: no MSI cap or BAR0 SKIP (reported honestly)</code></li><li><code>[nic_rw_test] no NICs registered =&gt; SKIP</code></li><li>QEMU 中的 <code>wifi scan</code>：如实的&quot;no radio&quot;输出</li></ul><p>解读规则：<strong>以如实跳过收尾的套件什么也没测</strong>。 如果你预期硬件在场（你接了设备、传了 QEMU flag），如实跳过意味着探针没找到它 — 去查总线 （<code>lspci</code>、<code>usb</code>），而不是查测试。</p><h2 id="_4-健康优先-—-三个告警位" tabindex="-1">4. 健康优先 — 三个告警位 <a class="header-anchor" href="#_4-健康优先-—-三个告警位" aria-label="Permalink to &quot;4. 健康优先 — 三个告警位&quot;">​</a></h2><p>健康监视器每秒采样并恰好升起三种告警（klog WARN）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alarm: memory &gt;90% used (&lt;used&gt;/&lt;total&gt; KiB)</span></span>
<span class="line"><span>alarm: &lt;n&gt; active tasks (&gt;64)</span></span>
<span class="line"><span>alarm: CPU &gt;=90% busy for 10 consecutive seconds</span></span></code></pre></div><p>在深潜任何&quot;慢&quot;或&quot;怪&quot;的机器之前，运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; health              # one snapshot: cpu/mem/heap/tasks/disk/net</span></span>
<span class="line"><span>ush&gt; health watch        # live monitor until ENTER</span></span>
<span class="line"><span>ush&gt; health export       # write the report to a file</span></span></code></pre></div><p>告警还作为额外的喂狗源接入 watchdog 槽 0 （&quot;system-heartbeat&quot;）：活着但告警的系统持续喂狗； 死了的停止，WP-11 panic 路径（转储 + crashlog + 策略） 触发。所以一台&quot;静默&quot;重启的机器很可能先告过警 — 下次启动的 <code>health</code> 加 <code>/var/log/kernel.log</code> 会讲述 故事。</p><h2 id="_5-日志级别过滤-—-你从未见过的消息" tabindex="-1">5. 日志级别过滤 — 你从未见过的消息 <a class="header-anchor" href="#_5-日志级别过滤-—-你从未见过的消息" aria-label="Permalink to &quot;5. 日志级别过滤 — 你从未见过的消息&quot;">​</a></h2><p>klog 有 5 个级别（DEBUG 0 … FATAL 4），带逐级别发射 开关、活动过滤器和全局级别。如果某行从不出现：</p><ul><li><strong>级别被关</strong>：<code>logctl status</code> 显示活动级别与 逐级掩码；<code>logctl level -1</code> 完全静音。用 <code>logctl enable debug</code>（或你需要的级别）重新启用。</li><li><strong>过滤器</strong>吃掉了它：<code>logctl filter</code> 设置作用于活动 通道以及 dmesg/logcat 回放。<code>logctl filter clear</code> 重置。</li><li><strong>环形已回绕</strong>：1024 条，覆盖被计数 — dmesg 页脚 <code>-- &lt;shown&gt; lines (ring &lt;n&gt;/1024, dropped &lt;d&gt;) --</code> 显示 丢弃。<code>dmesg 1024</code> 看整个窗口。</li><li>你看错了通道：<code>logctl flush</code> 写 <code>/var/log/kernel.log</code>（rotate 保留 3 份：kernel.log.1 ...）。</li></ul><p>快速解除隐藏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; logctl level 0           # everything</span></span>
<span class="line"><span>ush&gt; logctl test              # emits one line per level (module klogtest)</span></span>
<span class="line"><span>ush&gt; logcat -l debug -f       # follow everything live; ENTER exits</span></span></code></pre></div><p><code>logctl test</code> 是校准工具：如果它的 5 行出现， 管线正常，你的目标消息确实没有被发出。</p><h2 id="_6-crashlog-—-你忘了它存在的-32-槽历史" tabindex="-1">6. crashlog — 你忘了它存在的 32 槽历史 <a class="header-anchor" href="#_6-crashlog-—-你忘了它存在的-32-槽历史" aria-label="Permalink to &quot;6. crashlog — 你忘了它存在的 32 槽历史&quot;">​</a></h2><p><code>crashlog</code> 将每次 panic 记入 32 条环形（字段含 vector、rip、rsp、cr2、tid/pid、任务名），刷写到 <code>/var/log/crash.log</code>；核心转储去 <code>/var/crash/core.dump</code>。 任何不明复位之后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; crashlog          # were there panics you never saw?</span></span>
<span class="line"><span>ush&gt; dumpinfo          # core dump buffer status</span></span>
<span class="line"><span>ush&gt; dmesg 100         # this boot&#39;s klog</span></span>
<span class="line"><span>ush&gt; cat /var/log/crash.log</span></span></code></pre></div><p>空输出打印 <code>no dump captured yet (trigger: crashtest panic|exc|pf)</code> — 这也是在健康机器上验证该机制的方法。 #DF panic 刻意最小化（一条静态串口行，无记录/转储/刷写 — KNOWN_ISSUES 中已声明）：如果机器带着单行横幅死去， 检查<strong>串口</strong>，不是 crashlog。</p><h2 id="_7-静默不更新的-ota-—-六因链" tabindex="-1">7. 静默不更新的 OTA — 六因链 <a class="header-anchor" href="#_7-静默不更新的-ota-—-六因链" aria-label="Permalink to &quot;7. 静默不更新的 OTA — 六因链&quot;">​</a></h2><p><code>update</code>/<code>checkupdate</code> 安静地失败是经典的静默失败， 因为链路多半在代码内而非控制台文本中失败。按序 走完六因：</p><table tabindex="0"><thead><tr><th>#</th><th>原因</th><th>如何看见</th><th>修复</th></tr></thead><tbody><tr><td>1</td><td><code>update_url</code> 错误（坏 scheme/拼写）</td><td><code>config get update_url</code></td><td><code>config set update_url http://host/path</code>（必须 http:// 或 https://）</td></tr><tr><td>2</td><td>DNS 无法解析更新主机</td><td><code>dns &lt;host&gt;</code> → <code>DNS resolution failed</code></td><td>修复 DNS 服务器（重跑 <code>dhcp</code>，或设置 <code>ip &lt;a&gt; &lt;m&gt; &lt;g&gt;</code> 并检查 DNS 字段）</td></tr><tr><td>3</td><td>无 A/B 磁盘</td><td><code>update status</code> 缺 <code>A/B disk: present</code></td><td><code>lsblk</code> → <code>abdisk &lt;dev&gt;</code>（destructive；向导防护）</td></tr><tr><td>4</td><td>签名/校验失败</td><td>重跑 <code>update</code> — <code>&lt;why&gt;</code> 为 <code>SHA256 mismatch</code> / <code>package (tar.gz) invalid</code></td><td>重新下载；核对服务器的 package_sha256</td></tr><tr><td>5</td><td>版本比较认为已是最新</td><td><code>checkupdate</code> 打印 <code>Current version is up to date.</code></td><td>不是失败 — 源的版本字段必须高于你的；检查服务器的 update.json</td></tr><tr><td>6</td><td>网络完全不通</td><td><code>ip</code> 显示 0.0.0.0；<code>ping &lt;gw&gt;</code> 失败</td><td><code>dhcp</code>（或静态 <code>ip</code>），然后复查</td></tr></tbody></table><p>两条额外的安静路径：配置中的 <code>online_update=no</code> 使 <strong>autoupdate</strong> 后台路径静默跳过（<code>[autoupdate] skipped: network not ready</code> 仅在 klog） — <code>config get online_update</code>； <code>auto_check=no</code> 同样禁用启动时检查。</p><p>5 步 <code>update</code> 向导（无参数）按序走因 1→3→6 （IP 探测 → DHCP 提议 → A/B 磁盘探测 → DNS → 检查 → 安装）， 因此拿不准时直接无参数运行 <code>update</code> 并阅读失败的 <code>[n/5]</code> 步。</p><h2 id="_8-串口回显与被吃掉的-e-—-容错阅读" tabindex="-1">8. 串口回显与被吃掉的 <code>&quot;e&quot;</code> — 容错阅读 <a class="header-anchor" href="#_8-串口回显与被吃掉的-e-—-容错阅读" aria-label="Permalink to &quot;8. 串口回显与被吃掉的 \`&quot;e&quot;\` — 容错阅读&quot;">​</a></h2><p>串口控制台既是输入也是输出通道；当客户机在打印的 同时回显你的按键，回显可能与在途输出重叠。经典 伪影：<code>[ocse]</code> 这样的带括号标签变成 <code>[ega]</code> 等等 — 准确地说：串口回显重叠<strong>吃掉 <code>ega]</code> 形片段的 前导 <code>e</code></strong>（工具链称之为 <code>ega]</code> 现象）。你在屏幕上 看到的可能是客户机所打印内容的字符错位版本。</p><p>容错阅读规则（E2E 工具链用的同一套）：</p><ul><li>grep 引导输出时把 <code>[tag]</code> 括号视为<strong>可选</strong> — 匹配内部词，不匹配标点。</li><li>匹配前剥离回显的命令行（客户机回显你输入的， 然后打印结果）。</li><li>预期 ANSI CSI 序列交错；正则前剥离。</li><li>串口链路无法承载的按键（方向键、Home/End）必须经 QEMU monitor 的 <code>sendkey</code> 送入，而不是敲转义码 — CSI 字节经 TCP 套接字在引导菜单时刻到达得太晚。</li><li>已知抖动：QEMU 在 HMP screendump 之后偶发丢弃串口 RX 字节（经内核内 RX 追踪验证） — 绝不在功能轮次 中途截图；抖动的检查要隔离重跑。</li></ul><p>如果唯一的症状是一个怪字符，先重跑命令再调试 OS：通常是链路，不是内核。</p><h2 id="_9-什么都没发生-检查单" tabindex="-1">9. &quot;什么都没发生&quot;检查单 <a class="header-anchor" href="#_9-什么都没发生-检查单" aria-label="Permalink to &quot;9. &quot;什么都没发生&quot;检查单&quot;">​</a></h2><ol><li><code>health</code> — 有告警吗？（内存/任务/CPU）</li><li><code>dmesg 100</code> — 该家族有任何 WARN/ERROR 吗？（留意 级别过滤器：<code>logctl status</code>）</li><li><code>crashlog</code> + <code>dumpinfo</code> — 早先有什么死掉了吗？</li><li>重新运行命令并观察<strong>返回路径</strong>：静默的 <code>-1</code> 通常意味着刻意拒绝（保护盘、guard 通道、 已禁用特性 — 见 §2）。</li><li>输出是被<strong>捕获</strong>的吗（§1）？用裸命令而非 向导运行该 op，或反过来。</li><li>OTA 形状的问题 → 六因链（§7）。</li><li>单个乱码字符 → 串口回显（§8）；先重跑。</li><li>仍然什么都没有：捕获串口（<code>-serial file:boot.log</code>）并检查 klog 环形中从未到达屏幕的 FATAL 行 — 串口控制台是权威。</li></ol><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./error-codes.html">error-codes.md</a> — 安静拒绝背后的代码</li><li><a href="./error-catalog.html">error-catalog.md</a> — 按子系统排列的 大声失败</li><li><a href="./../manual/hidden-commands.html">../manual/hidden-commands.md</a> — 令内核路径打印判定的桩</li><li><a href="./qemu-debugging.html">qemu-debugging.md</a> — 捕获技术</li></ul>`,53)])])}const u=o(c,[["render",l]]);export{g as __pageData,u as default};
